// Assertions: HTTP response, valid JSON object, expected referral membership and routing.
import groovy.json.JsonSlurper

def step = testRunner.testCase.getTestStepByName('02 Execute REST Request')
def response = step.getTestRequest().getResponse()
assert response != null : 'No HTTP response - verify host, SSL, authentication and REST path'
def status = response.getStatusCode()
assert status >= 200 && status < 300 : 'Expected HTTP 2xx but received ' + status + ' | ' + (step.getPropertyValue('Response') ?: '').take(500)
def raw = step.getPropertyValue('Response')
assert raw?.trim() : 'Empty response body'
def root
try { root = new JsonSlurper().parseText(raw) }
catch (Exception ex) { throw new AssertionError('Response is not valid JSON: '+ ex.message) }
assert root instanceof Map : 'Expected a JSON response object'
def area = root.auDecisionArea
assert area instanceof Map : 'Missing auDecisionArea response object'
assert area.containsKey('wuc121_routing_destination') : 'Missing wuc121_routing_destination'
assert area.wuc121_routing_reasons instanceof List : 'Missing wuc121_routing_reasons array'
def reasons = area.wuc121_routing_reasons.findAll { it instanceof Map }.collect { it.wuc121_rsn_code == null ? '' : it.wuc121_rsn_code.toString().trim().padLeft(3,'0') }
// Do not compare padded zero/empty OCCURS records.
reasons = reasons.findAll { it && it != '000' }
def required = ['063']
def forbidden = []
required.each { code -> assert reasons.contains(code) : 'Missing expected referral '+code+'; actual='+reasons }
forbidden.each { code -> assert !reasons.contains(code) : 'Unexpected referral '+code+'; actual='+reasons }
def destination = area.wuc121_routing_destination == null ? '' : area.wuc121_routing_destination.toString().trim()
assert destination == 'UND' : 'Expected routing destination UND, got '+destination
// No driver identifier assertion for policy-only referrals
assert reasons.count('063') == 1 : 'Expected deduplicated single 063, actual '+reasons
log.info('PASS '+testRunner.testCase.name+' | HTTP '+status+' | route='+destination+' | referrals='+reasons)
